package local.tvmorph.tv;
import android.content.*;import android.security.keystore.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import android.util.Base64;import org.json.*;
/** Credentials encrypted by a non-exportable AndroidKeyStore AES key; excluded from backup. */
final class LanVault {
 static javax.crypto.SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("morph-lan-v1")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("morph-lan-v1",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}return (javax.crypto.SecretKey)ks.getKey("morph-lan-v1",null);}
 static void save(Context c,String origin,String user,String password)throws Exception{if(user.length()>256||password.length()>512||user.contains(":"))throw new Exception("Invalid credentials.");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());byte[] data=cipher.doFinal(new JSONObject().put("u",user).put("p",password).toString().getBytes("UTF-8"));String encoded=Base64.encodeToString(cipher.getIV(),2)+":"+Base64.encodeToString(data,2);c.getSharedPreferences("morph-lan-secrets",0).edit().putString(origin,encoded).apply();}
 static String auth(Context c,String origin)throws Exception{String value=c.getSharedPreferences("morph-lan-secrets",0).getString(origin,"");if(value.isEmpty())return "";String[] parts=value.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],2)));JSONObject obj=new JSONObject(new String(cipher.doFinal(Base64.decode(parts[1],2)),"UTF-8"));return "Basic "+Base64.encodeToString((obj.getString("u")+":"+obj.getString("p")).getBytes("UTF-8"),2);}
 static void remove(Context c,String origin){c.getSharedPreferences("morph-lan-secrets",0).edit().remove(origin).apply();}
}
